import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  city: string;
  street: string;
  comment: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  city: '',
  street: '',
  comment: '',
};

export default function RegistrationWizard({
  onSubmit,
}: {
  onSubmit: (data: RegistrationData) => void;
}) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);

  const set = (key: keyof RegistrationData) => (
    event: { target: { value: string } },
  ) => setData((prev) => ({ ...prev, [key]: event.target.value }));

  const emailError =
    data.email.length > 0 && !data.email.includes('@')
      ? 'Укажите адрес с символом @'
      : undefined;

  const contactsReady = data.name.trim() !== '' && data.email.includes('@');
  const addressReady = data.city.trim() !== '' && data.street.trim() !== '';
  const canGoNext = step === 0 ? contactsReady : step === 1 ? addressReady : true;

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (step < steps.length - 1) {
          if (canGoNext) setStep(step + 1);
          return;
        }
        onSubmit(data);
      }}
      style={{ display: 'grid', gap: '24px' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            autoComplete="name"
            value={data.name}
            onChange={set('name')}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            autoComplete="email"
            value={data.email}
            onChange={set('email')}
            errorText={emailError}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxInputField
            label="Город"
            required
            autoComplete="address-level2"
            value={data.city}
            onChange={set('city')}
          />
          <JxInputField
            label="Улица и дом"
            required
            autoComplete="street-address"
            value={data.street}
            onChange={set('street')}
          />
          <JxTextareaField
            label="Комментарий для курьера"
            rows={3}
            maxLength={300}
            value={data.comment}
            onChange={set('comment')}
            helperText={`${data.comment.length}/300`}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxDivider label="Проверьте данные" />
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
              color: 'var(--jx-text)',
              fontFamily: 'var(--jx-font-sans)',
            }}
          >
            <dt style={{ color: 'var(--jx-text-2)' }}>Имя</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.name}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Почта</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.email}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Город</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.city}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Адрес</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.street}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Комментарий</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>
              {data.comment.trim() === '' ? 'Без комментария' : data.comment}
            </dd>
          </dl>
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep(Math.max(step - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={!canGoNext}>
          {step === steps.length - 1 ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

